//! Generates the Rust types of the Swarm models from their JSON Schema bundle.
//!
//! The Pydantic models stay the single source: the bundle is exported from them, and this crate turns it into Rust
//! structs with typify. The output is deterministic, so a continuous integration job can fail when it is out of date.

mod error;

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;
use typify::{TypeSpace, TypeSpaceSettings};

pub use error::CodegenError;

/// The first line of every generated file.
pub const HEADER: &str = "// @generated by swarm-models-codegen from the JSON Schema bundle. Do not edit by hand.";

/// Reads a file, naming it in the error.
fn read(path: &Path) -> Result<String, CodegenError> {
    fs::read_to_string(path).map_err(|source| CodegenError::Io {
        path: path.to_path_buf(),
        source,
    })
}

/// Rewrites `#/$defs/` references into `#/definitions/`, which is where schemars 0.8 looks.
fn rewrite_references(value: &mut Value) {
    match value {
        Value::String(text) => {
            if let Some(rest) = text.strip_prefix("#/$defs/") {
                *text = format!("#/definitions/{rest}");
            }
        }
        Value::Array(items) => items.iter_mut().for_each(rewrite_references),
        Value::Object(map) => map.values_mut().for_each(rewrite_references),
        _ => {}
    }
}

/// Renders the Rust source of every `$defs` entry of a schema bundle.
///
/// The text starts with [`HEADER`] and a newline, and is the same for the same bundle.
///
/// # Errors
///
/// Returns an error when the text is not a JSON Schema, when typify refuses a definition, or when the generated code
/// does not parse.
pub fn render(schema: &str) -> Result<String, CodegenError> {
    let mut bundle: Value = serde_json::from_str(schema).map_err(CodegenError::Schema)?;
    let object = bundle
        .as_object_mut()
        .ok_or_else(|| CodegenError::Invalid("the bundle must be a JSON object".to_owned()))?;
    if let Some(definitions) = object.remove("$defs") {
        object.insert("definitions".to_owned(), definitions);
    }
    rewrite_references(&mut bundle);
    let root: schemars::schema::RootSchema = serde_json::from_value(bundle).map_err(CodegenError::Schema)?;

    let mut type_space = TypeSpace::new(&TypeSpaceSettings::default());
    type_space
        .add_ref_types(root.definitions)
        .map_err(|error| CodegenError::Generation(error.to_string()))?;
    let file = syn::parse2::<syn::File>(
        type_space
            .to_stream()
            .map_err(|error| CodegenError::Generation(error.to_string()))?,
    )
    .map_err(CodegenError::Syntax)?;
    Ok(format!("{HEADER}\n{}", prettyplease::unparse(&file)))
}

/// Tells whether the generated file differs from what the schema renders to.
///
/// A missing output is stale.
///
/// # Errors
///
/// Returns an error when the schema cannot be read or rendered, or when the output exists but cannot be read.
pub fn is_stale(schema: &Path, output: &Path) -> Result<bool, CodegenError> {
    let expected = render(&read(schema)?)?;
    if !output.exists() {
        return Ok(true);
    }
    Ok(read(output)? != expected)
}

/// Renders the schema and writes the result to the output, creating its folder if needed.
///
/// # Errors
///
/// Returns an error when the schema cannot be read or rendered, or when the output cannot be written.
pub fn write(schema: &Path, output: &Path) -> Result<(), CodegenError> {
    let text = render(&read(schema)?)?;
    if let Some(folder) = output.parent() {
        fs::create_dir_all(folder).map_err(|source| CodegenError::Io {
            path: folder.to_path_buf(),
            source,
        })?;
    }
    fs::write(output, text).map_err(|source| CodegenError::Io {
        path: output.to_path_buf(),
        source,
    })
}

/// The path of the schema bundle exported from the Pydantic models.
#[must_use]
pub fn default_schema_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../python/swarm-models/schemas/swarm_models.schema.json")
}

/// The path of the generated Rust file in the `swarm-models` crate.
#[must_use]
pub fn default_output_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../swarm-models/src/generated.rs")
}
